      delete persistedJob.__registryRows;
      const data = await runtimeRequest('POST', '/api/v1/wb/runtime/jobs/' + encodeURIComponent(taskId) + '/transition', {
        rowVersion: expectedRowVersion,
        eventType: 'N8N_JOB_TRANSITION',
        message: "Persist Job" + ' 写入 PostgreSQL runtime',
        job: persistedJob,
        ...(registryRows.length ? { registryRows } : {}),
      });
      return toItems(data.job || data);
    } catch (error) {
      if (Number(error?.httpStatus || 0) !== 409) throw error;
      // 旧执行结果不得通过读取最新 rowVersion 后重放。冲突时只回读当前状态，
      // 由调度器下一轮重新加载任务并计算；intent 冲突也不得继续调用 WB 写接口。
      const latestData = await runtimeRequest('GET', '/api/v1/wb/runtime/jobs/' + encodeURIComponent(taskId), undefined);
      const latest = latestData.job || latestData || {};
      return toItems({ ...latest, __transitionConflict: true, __transitionSource: "Persist Job" });
    }
  }
  if ("wb_publish_jobs" === 'wb_product_registry') {
    const rows = $input.all().map((item) => item.json || {});
    let taskId = '';
    try { taskId = String($('Build Step').first().json.job?.task_id || ''); } catch (_) {}
    if (!taskId) try { taskId = String($('When Executed by Another Workflow').first().json.taskId || ''); } catch (_) {}
    if (!taskId) taskId = 'unknown';
    const data = await runtimeRequest('POST', '/api/v1/wb/runtime/jobs/' + encodeURIComponent(taskId) + '/registry', { rows });
    return toItems(data.items || []);
  }
  if ("wb_publish_jobs" === 'wb_system_errors') {
    const data = await runtimeRequest('POST', '/api/v1/wb/runtime/errors', $json);
    return toItems(data.error || data);
  }
  return migrated("Persist Job");
})();

