      const replay = runtime.mediaReplayFromByVendor && typeof runtime.mediaReplayFromByVendor === 'object' ? { ...runtime.mediaReplayFromByVendor } : {};
      transientFailures.forEach((entry) => {
        const vendorCode = String(entry.vendorCode || '');
        const photoNumber = Number(entry.photoNumber || 0);
        if (!vendorCode || photoNumber < 1) return;
        replay[vendorCode] = replay[vendorCode] ? Math.min(Number(replay[vendorCode]), photoNumber) : photoNumber;
      });
      runtime.mediaReplayFromByVendor = replay;
    }
    const rootSummary = transientFailures.map((entry) => (entry.kind === 'video' ? '视频' : '图片 ' + entry.photoNumber)
      + (entry.vendorCode ? ' (' + entry.vendorCode + ')' : '')
      + (entry.status ? ' HTTP ' + entry.status : '')
      + (entry.error ? ': ' + entry.error : '')).join('; ');
    const retryAfterSeconds = Math.max(0, ...transientFailures.map((entry) => Number(entry.retryAfterSeconds || 0)));
    const previousRetryAfter = headers['retry-after'] || headers['Retry-After'];
    if (retryAfterSeconds > parseRetryAfterSeconds(previousRetryAfter)) headers['Retry-After'] = String(retryAfterSeconds);
    const gatewayDeliveryState = transientFailures.some((entry) => entry.deliveryState === 'UNKNOWN') ? 'UNKNOWN'
      : transientFailures.every((entry) => entry.deliveryState === 'NOT_SENT') ? 'NOT_SENT' : 'UNKNOWN';
    return transient('MEDIA_BATCH_TRANSIENT', '媒体批次存在 ' + transientFailures.length + ' 个目标的首个临时或未知错误：' + rootSummary + '；先回读商品卡后续传', {
      resumeState: verifyingState, deliveryState: gatewayDeliveryState,
      safeShortRetry: gatewayDeliveryState === 'NOT_SENT' && transientFailures.every((entry) => entry.retryClass === 'RETRYABLE'),
    });
  }

  closeNetworkRecovery(verifyingState);
  return persist(verifyingState, 2);
}

const lookupStage = ['CARDS_LIST', 'CREATE_ONLY_CHECK'].includes(stage);
if (lookupStage) {
  const lookupCodes = [...new Set((step.request.lookupVendorCodes || []).map(String).filter(Boolean))];
  const expectedResponses = stage === 'CREATE_ONLY_CHECK' ? lookupCodes.length * 2 : lookupCodes.length;
  const assigned = new Set();
  let pairingInvalid = false;
  responseDetails.forEach((entry, index) => {
    const lookupIndex = entry.pairedIndex ?? index;
    if (!Number.isInteger(lookupIndex) || lookupIndex < 0 || lookupIndex >= expectedResponses || assigned.has(lookupIndex)) pairingInvalid = true;
    assigned.add(lookupIndex);
  });
  if (!lookupCodes.length || responseDetails.length !== expectedResponses || assigned.size !== expectedResponses || pairingInvalid) {
    runtime.audit.push({
      at: new Date().toISOString(), event: 'LOOKUP_BATCH_INCOMPLETE', executionId: String($execution.id),
      stage, hostname, method: String(step.request.method || ''), attempt: Number(job.stage_attempt || 0) + 1,
      expectedResponses, actualResponses: responseDetails.length,
    });
    return transient('WB_LOOKUP_INCOMPLETE', 'WB 卡片查询批次响应不完整，整批保持原状态后重试', {
      deliveryState: 'NOT_SENT', safeShortRetry: true,
    });
  }
}

if (step.gatewayMode === 'MERCHROUTE_VAULT') {
  const validDeliveryStates = new Set(['NOT_SENT','UNKNOWN','RESPONDED']);
  const validRetryClasses = new Set(['NONE','READBACK_REQUIRED','RETRYABLE','PERMANENT']);
  const expectedRequestRef = String(step.request.requestRef || '');
  const invalidGatewayResponse = responseDetails.find((entry) => {
    const actualRequestRef = String(entry.raw?.requestRef || '');
    const requestRefMatches = !expectedRequestRef
      || (lookupStage
        ? (actualRequestRef === expectedRequestRef || actualRequestRef.startsWith(expectedRequestRef + ':'))
        : actualRequestRef === expectedRequestRef);
    return !validDeliveryStates.has(String(entry.deliveryState || ''))
      || !validRetryClasses.has(String(entry.retryClass || ''))
      || !requestRefMatches;
  });
  if (invalidGatewayResponse) {
    const safeRead = isSafeReadStage(stage);
    runtime.audit.push({
      at: new Date().toISOString(), event: 'GATEWAY_RESPONSE_INVALID', executionId: String($execution.id),
      stage, hostname, method: String(step.request.method || ''), requestRef: expectedRequestRef,
    });
    return transient('GATEWAY_RESPONSE_INVALID', 'MerchRoute WB 网关响应缺少 deliveryState/retryClass/requestRef，禁止按 HTTP 200 推进', {
      deliveryState: safeRead ? 'NOT_SENT' : 'UNKNOWN', safeShortRetry: safeRead,
    });
  }
}

const nodeFailure = responseDetails.find((entry) => entry.status === 0 || entry.errorCode || entry.errorMessage);
if (nodeFailure) {
  const code = String(nodeFailure.errorCode || 'WB_NETWORK_ERROR').toUpperCase();
  const message = safe(nodeFailure.errorMessage || 'WB 请求未返回 HTTP 响应');
  runtime.audit.push({
    at: new Date().toISOString(), event: 'HTTP_TRANSPORT_ERROR', executionId: String($execution.id),
    stage, hostname, method: String(step.request.method || ''), attempt: Number(job.stage_attempt || 0) + 1,
    errorCode: code, message,
  });
  if (nodeFailure.status === 0 || isTransientNetworkError(code, message)) {
    const gatewayDelivery = ['NOT_SENT','UNKNOWN','RESPONDED'].includes(nodeFailure.deliveryState) ? nodeFailure.deliveryState : '';
    const deliveryState = gatewayDelivery || (isSafeReadStage(stage) ? 'NOT_SENT' : 'UNKNOWN');
    return transient(code, message, {
      deliveryState,
      safeShortRetry: nodeFailure.retryClass === 'RETRYABLE' || (isSafeReadStage(stage) && deliveryState !== 'UNKNOWN'),
    });
  }
  return businessFail(code === 'WB_NETWORK_ERROR' ? 'WB_TRANSPORT_ERROR' : code, message, Boolean((runtime.cards || []).length));
}

if ([408, 425].includes(status)) return transient('WB_UPSTREAM_' + status, 'WB API 暂时无法确认请求结果', {
  deliveryState: ['NOT_SENT','UNKNOWN'].includes(primary.deliveryState) ? primary.deliveryState : (isSafeReadStage(stage) ? 'NOT_SENT' : 'UNKNOWN'),
  safeShortRetry: primary.retryClass === 'RETRYABLE' || isSafeReadStage(stage),
});
if (status === 429) return transient('WB_RATE_LIMIT', 'WB API 限流', isSafeReadStage(stage)
  ? { deliveryState: primary.deliveryState || 'NOT_SENT', safeShortRetry: true }
  : { deliveryState: primary.deliveryState || 'UNKNOWN', safeShortRetry: primary.retryClass === 'RETRYABLE' });
if (status >= 500) return transient('WB_UPSTREAM_' + status, 'WB API 暂时不可用', isSafeReadStage(stage)
  ? { deliveryState: primary.deliveryState || 'NOT_SENT', safeShortRetry: true }
  : { deliveryState: primary.deliveryState || 'UNKNOWN', safeShortRetry: primary.retryClass === 'RETRYABLE' });
closeNetworkRecovery(stage);
if ([401, 403].includes(status)) return persist('BLOCKED_AUTH', 86400, 'WB_AUTH_FAILED', 'WB API 返回 ' + status + '，请检查 Token 权限或有效期');
if (stage !== 'PRICE_TASK' && (status < 200 || status >= 300) && status !== 208) {
  return businessFail('WB_HTTP_' + status, 'WB API 返回业务错误 ' + status + ': ' + safe(body?.errorText || body?.message || body?.detail));
}
if (body && body.error === true) return businessFail('WB_BODY_ERROR', safe(body.errorText || 'WB 响应标记 error=true'));

if (stage === 'TNVED_LIST') {
  const requested = String(product.compliance?.tnved || '');
  const values = Array.isArray(body?.data) ? body.data : [];
  const match = values.find((entry) => String(entry?.tnved || '') === requested);
  if (!match) return persist('BLOCKED_COMPLIANCE', 86400, 'TNVED_NOT_ALLOWED', '当前 WB 类目未返回完全匹配的 TNVED：' + requested);
  if (Boolean(match.isKiz) !== Boolean(product.compliance?.kizMarked)) {
    return persist('BLOCKED_COMPLIANCE', 86400, 'KIZ_MISMATCH', '商品 kizMarked 与 WB TNVED 目录的 isKiz 不一致');
  }
  runtime.compliance = { tnved: requested, isKiz: Boolean(match.isKiz), verifiedAt: new Date().toISOString() };
  job.stage_attempt = 0;
  const nextState = String(runtime.afterComplianceState || 'CARD_RECONCILING');
  runtime.afterComplianceState = '';
  return persist(nextState, 0);
}

if (stage === 'BARCODE_ALLOCATE') {
  const values = Array.isArray(body?.data) ? body.data.map(String) : [];
  const missing = runtime.missingBarcodeSlots || [];
  if (values.length < missing.length) return businessFail('BARCODE_RESPONSE_INVALID', 'WB 返回条码数量不足');
  runtime.barcodes = runtime.barcodes || {};
  missing.forEach((slot, index) => { runtime.barcodes[slot.variantIndex + ':' + slot.sizeIndex] = values[index]; });
  runtime.missingBarcodeSlots = [];
  job.stage_attempt = 0;
  const nextState = String(runtime.afterBarcodeState || 'CARD_RECONCILING');
  runtime.afterBarcodeState = '';
  return persist(nextState, 1);
}
if (stage === 'MEDIA_TRIM') {
  const completed = runtime.mediaTrimIntent || {};
  runtime.audit.push({ at: new Date().toISOString(), event: 'MEDIA_TRIM_RESPONSE', executionId: String($execution.id), vendorCode: completed.vendorCode, nmID: completed.nmID, desired: completed.desired, status });
  runtime.mediaTrimQueue = (runtime.mediaTrimQueue || []).filter((entry) => String(entry.vendorCode) !== String(completed.vendorCode));
  runtime.mediaTrimIntent = null;
  job.stage_attempt = 0;
  return runtime.mediaTrimQueue.length ? persist('MEDIA_TRIM_READY', 1) : persist('VIDEO_RECONCILING', 2);
}

if (stage === 'CARD_WRITE') {
  job.stage_attempt = 0;
  job.wb_request_ref = 'content:' + String(runtime.cardOperation || 'write') + ':' + String(runtime.cardSubmittedAt || new Date().toISOString());
  if (String(step.request.operation || '') === 'CARD_UPLOAD' && runtime.cardRecovery?.active) {
    runtime.cardRecovery = {
      ...runtime.cardRecovery, attemptNo: Number(step.request.attemptNo || runtime.cardRecovery.attemptNo || 1),
      lastAttemptRespondedAt: new Date().toISOString(),
      finalReadbackOnly: Number(step.request.attemptNo || runtime.cardRecovery.attemptNo || 1) >= 2,
    };
  }
  return persist('CARD_WAITING', 30);
}

if (stage === 'CREATE_ONLY_CHECK') {
  const vendorCodes = [...new Set((step.request.lookupVendorCodes || []).map(String).filter(Boolean))];
  const plan = vendorCodes.flatMap((vendorCode) => [
    { vendorCode, scope: 'active' },
    { vendorCode, scope: 'trash' },
  ]);
  if (!vendorCodes.length || responseDetails.length !== plan.length) {
    return persist('FAILED', 0, 'CREATE_ONLY_CHECK_INCOMPLETE', 'CREATE_ONLY 防线未返回完整的普通卡和回收站检查结果');
  }
  const matches = [];
  const assignedLookups = new Set();
  for (let index = 0; index < responseDetails.length; index++) {
    const entry = responseDetails[index];
    const lookupIndex = entry.pairedIndex ?? index;
    const lookup = plan[lookupIndex];
    if (!lookup || assignedLookups.has(lookupIndex)) {
      return persist('FAILED', 0, 'CREATE_ONLY_CHECK_INCOMPLETE', 'CREATE_ONLY 防线响应配对缺失或重复，已禁止建卡');
    }
    assignedLookups.add(lookupIndex);
    const cards = entry.body?.cards || entry.body?.data?.cards || entry.body?.data || [];
    if (!Array.isArray(cards)) continue;
    cards.filter((card) => String(card?.vendorCode || '') === lookup.vendorCode).forEach((card) => {
      matches.push({
        scope: lookup.scope, vendorCode: lookup.vendorCode,
        nmID: String(card?.nmID || ''), imtID: String(card?.imtID || ''),
      });
    });
  }
  runtime.audit.push({
    at: new Date().toISOString(), event: 'CREATE_ONLY_CHECKED', executionId: String($execution.id),
    vendorCodes, activeMatches: matches.filter((entry) => entry.scope === 'active').length,
    trashMatches: matches.filter((entry) => entry.scope === 'trash').length,
  });
  const cardRecovery = runtime.cardRecovery && typeof runtime.cardRecovery === 'object' ? runtime.cardRecovery : null;
  if (cardRecovery?.active && runtime.cardOperation === 'create') {
    const duplicateIdentity = vendorCodes.find((vendorCode) => new Set(matches
      .filter((entry) => entry.vendorCode === vendorCode)
      .map((entry) => String(entry.nmID || '')).filter(Boolean)).size > 1);
    if (duplicateIdentity) {
      return businessFail('CARD_IDENTITY_AMBIGUOUS', '建卡 UNKNOWN 回读发现同一 vendorCode 对应多个 nmID，禁止自动选择: ' + duplicateIdentity, true);
    }
    cardRecovery.lastActiveTrashCheckAt = new Date().toISOString();
    cardRecovery.lastActiveMatches = matches.filter((entry) => entry.scope === 'active');
    cardRecovery.lastTrashMatches = matches.filter((entry) => entry.scope === 'trash');
    if (cardRecovery.lastTrashMatches.length) {
      runtime.existingCardMatches = matches;
      cardRecovery.finalReadbackOnly = true;
      return needsAttention('CARD_FOUND_IN_TRASH', '建卡 UNKNOWN 回读在 WB 回收站发现目标 vendorCode，禁止自动补投', true);
    }
    if (cardRecovery.lastActiveMatches.length) {
      cardRecovery.active = false;
      cardRecovery.resolvedBy = 'ACTIVE_CARD';
      cardRecovery.resolvedAt = new Date().toISOString();
      return persist('CARD_WAITING', 0, 'CARD_UPLOAD_RECONCILED', '建卡 UNKNOWN 已在普通商品卡中回读到目标身份');
    }
    cardRecovery.pendingProofActiveTrashAt = cardRecovery.lastActiveTrashCheckAt;
    return persist('CARD_ERROR_RECONCILING', 0, 'CARD_UNKNOWN_CHECKING_ERRORS', '普通卡与回收站均为空，继续核验 WB 建卡错误列表');
  }
  if (matches.length) {
    runtime.existingCardMatches = matches;
    return persist('BLOCKED_EXISTING_CARD', 315360000, 'BLOCKED_EXISTING_CARD', 'CREATE_ONLY 检测到 WB 普通商品卡或回收站商品卡，禁止创建或更新既有商品');
  }
  runtime.createOnlyGuard = { checkedAt: new Date().toISOString(), vendorCodes };
  job.stage_attempt = 0;
  return persist('CARD_CREATE_READY', 0);
}

if (stage === 'CARDS_ERROR_LIST') {
  const items = body?.data?.items || body?.items || [];
  const expected = new Set((product.variants || []).map((variant) => String(variant.vendorCode)));
  const submitted = Date.parse(runtime.cardCreateIntent?.lastAttemptAt || runtime.cardSubmittedAt || job.submitted_at || 0);
  const candidates = items.filter((item) => {
    const codes = (item.vendorCodes || []).map(String);
    return codes.some((code) => expected.has(code));
  });
  runtime.cardErrorCandidates = candidates.slice(0, 5).map((item) => ({
    batchUUID: String(item.batchUUID || ''), updatedAt: String(item.updatedAt || ''),
    vendorCodes: (item.vendorCodes || []).map(String),
  }));
  // WB 的 updatedAt 来自其服务端，本机 cardSubmittedAt 来自 n8n；允许 5 分钟
  // 时钟偏差，但不接受更早的历史失败批次。
  const match = candidates.find((item) => Date.parse(item.updatedAt || 0) >= submitted - 5 * 60 * 1000);
  if (match) {
    const rawErrors = match.errors;
    const messages = [];
    if (Array.isArray(rawErrors)) messages.push(...rawErrors.map(safe));
    else if (rawErrors && typeof rawErrors === 'object') {
      for (const code of match.vendorCodes || []) {
        const values = rawErrors[code];
        if (Array.isArray(values)) values.forEach((message) => messages.push(String(code) + ': ' + safe(message)));
        else if (values) messages.push(String(code) + ': ' + safe(values));
      }
    } else if (rawErrors) messages.push(safe(rawErrors));
    runtime.cardErrorBatchUUID = String(match.batchUUID || '');
    return businessFail('CARD_REJECTED', messages.join('; ') || 'WB 拒绝了卡片');
  }
  runtime.lastCardErrorCheckAt = new Date().toISOString();
  runtime.cardErrorChecks = Number(runtime.cardErrorChecks || 0) + 1;
  const cardRecovery = runtime.cardRecovery && typeof runtime.cardRecovery === 'object' ? runtime.cardRecovery : null;
  if (cardRecovery?.active && runtime.cardOperation === 'create') {
    const now = Date.now();
    const attemptNo = Number(cardRecovery.attemptNo || runtime.cardCreateIntent?.attemptNo || 1);
    const activeTrashAt = Date.parse(String(cardRecovery.pendingProofActiveTrashAt || ''));
    const previousCompleteProofAt = Date.parse(String(cardRecovery.lastCompleteProofAt || ''));
    if (!Number.isFinite(activeTrashAt) || (Number.isFinite(previousCompleteProofAt) && activeTrashAt <= previousCompleteProofAt)) {
      return persist('CARD_SUBMITTING', 0, 'CARD_UNKNOWN_FULL_PROOF_REQUIRED', '本轮错误列表前缺少对应的普通卡和回收站核验，重新执行完整只读证明');
    }
    cardRecovery.pendingProofActiveTrashAt = '';
    cardRecovery.lastCompleteProofAt = new Date(now).toISOString();
    cardRecovery.lastErrorListCheckAt = new Date(now).toISOString();
    if (attemptNo >= 2 || cardRecovery.finalReadbackOnly === true) {
      if (now >= Date.parse(job.stage_deadline_at || 0)) {
        return needsAttention('CARD_RETRY_RESULT_AMBIGUOUS', '第二次 CARD_UPLOAD 后普通卡、回收站和错误列表仍为空；禁止第三次写入');
      }
      return persist('CARD_SUBMITTING', 30, 'CARD_RETRY_READBACK_ONLY', '第二次 CARD_UPLOAD 结果仍未确认，继续只读核验，禁止再次补投');
    }
    const firstAttemptAt = Date.parse(String(cardRecovery.firstAttemptAt || runtime.cardCreateIntent?.firstAttemptAt || runtime.cardSubmittedAt || ''));
    const retryEligibleAt = Date.parse(String(cardRecovery.retryEligibleAt || ''));
    if (!Number.isFinite(firstAttemptAt) || !Number.isFinite(retryEligibleAt)) {
      return needsAttention('CARD_RECOVERY_IDENTITY_INVALID', '建卡 UNKNOWN 缺少首写时间或恢复门槛，禁止自动补投');
    }
    if (now < retryEligibleAt) {
      const delay = Math.max(30, Math.min(300, Math.ceil((retryEligibleAt - now) / 1000)));
      return persist('CARD_SUBMITTING', delay, 'CARD_UNKNOWN_READBACK_PENDING', '首写尚未满 30 分钟，继续核验普通卡、回收站和错误列表');
    }
    const proofRounds = Number(cardRecovery.proofRounds || 0);
    const lastProofAt = Date.parse(String(cardRecovery.lastProofRoundAt || ''));
    if (proofRounds < 1) {
      cardRecovery.proofRounds = 1;
      cardRecovery.lastProofRoundAt = new Date(now).toISOString();
      runtime.audit.push({ at: new Date(now).toISOString(), event: 'CARD_UNKNOWN_PROOF_ROUND', executionId: String($execution.id), round: 1, logicalIntentId: String(cardRecovery.logicalIntentId || '') });
      return persist('CARD_SUBMITTING', 60, 'CARD_UNKNOWN_SECOND_PROOF_PENDING', '首轮完整核验均为空，至少 60 秒后执行第二轮');
    }
    if (!Number.isFinite(lastProofAt) || now - lastProofAt < 60 * 1000) {
      const delay = Number.isFinite(lastProofAt) ? Math.max(1, Math.ceil((60 * 1000 - (now - lastProofAt)) / 1000)) : 60;
      return persist('CARD_SUBMITTING', delay, 'CARD_UNKNOWN_SECOND_PROOF_PENDING', '两轮完整核验必须至少间隔 60 秒');
    }
    if (proofRounds === 1) {
      cardRecovery.proofRounds = 2;
      cardRecovery.lastProofRoundAt = new Date(now).toISOString();
      cardRecovery.retryAuthorizedAt = new Date(now).toISOString();
      runtime.audit.push({ at: new Date(now).toISOString(), event: 'CARD_UNKNOWN_PROOF_ROUND', executionId: String($execution.id), round: 2, logicalIntentId: String(cardRecovery.logicalIntentId || '') });
      runtime.audit.push({ at: new Date(now).toISOString(), event: 'CARD_RETRY_AUTHORIZED', executionId: String($execution.id), logicalIntentId: String(cardRecovery.logicalIntentId || ''), attemptNo: 2 });
      return persist('CARD_CREATE_READY', 0, 'CARD_RETRY_AUTHORIZED', '两轮完整核验均为空，已授权同载荷补投一次');
    }
    return needsAttention('CARD_ATTEMPT_LIMIT_REACHED', 'CARD_UPLOAD 自动补投次数已用尽，禁止 attempt 3');
  }
  if (Date.now() < Date.parse(job.stage_deadline_at || 0)) {
    return persist('CARD_WAITING', 30, 'CARD_ERROR_NOT_READY', 'WB 错误列表暂未返回匹配批次，继续回读商品卡');
  }
  return needsAttention('CARD_RECONCILE_TIMEOUT', '平台可读累计 24 小时，卡片在成功与失败列表中仍未对账到；保留原任务供人工兜底');
}

if (stage === 'CARDS_LIST') {
  // 成功回读即打断网络失败链；后续异常必须从第一次快速退避重新计数。
  job.stage_attempt = 0;
  const combined = responseDetails.flatMap((entry) => {
    const cards = entry.body?.cards || entry.body?.data?.cards || entry.body?.data || [];
    return Array.isArray(cards) ? cards : [];
  });
  const unique = new Map();
  combined.forEach((card) => unique.set(String(card.vendorCode) + '|' + String(card.nmID), card));
  const list = Array.from(unique.values());
  const found = exactCards(list);
  const expectedVendorCodes = new Set((product.variants || []).map((variant) => String(variant.vendorCode)));
  const registryVendorCodes = new Set((Array.isArray(step.request.registryVendorCodes) ? step.request.registryVendorCodes : runtime.registryVendorCodes || []).map(String));
  const anchorCards = list.filter((card) => registryVendorCodes.has(String(card.vendorCode)) && !expectedVendorCodes.has(String(card.vendorCode)));
  const expectedCount = (product.variants || []).length;
  const currentState = stateAtRequest;
  const currentTaskOwnsCreateIntent = runtime.cardCreateIntent?.taskId === job.task_id
    && runtime.cardCreateIntent?.idempotencyKey === job.idempotency_key;
  const duplicateVendorCode = [...expectedVendorCodes].find((vendorCode) => found.filter((card) => String(card.vendorCode) === vendorCode).length > 1);
  if (duplicateVendorCode) return businessFail('CARD_IDENTITY_AMBIGUOUS', 'WB 返回同一 vendorCode 的多个 nmID，禁止自动选择: ' + duplicateVendorCode, true);
  if (submissionMode === 'COMPATIBLE_UPSERT' && found.length) {
    job.partial_effects = true;
    try { assertCompatibleCardOwnership(found); }
    catch (error) { return businessFail(String(error.code || 'COMPATIBLE_CARD_OWNERSHIP_MISMATCH'), safe(error.message), true); }
    runtime.isUpdate = true;
  }
  if (submissionMode === 'COMPATIBLE_UPSERT' && found.some((card) => Number(card.subjectID || card.subjectId) !== Number(runtime.expectedSubjectId))) {
    return businessFail('COMPATIBLE_SUBJECT_MISMATCH', '既有 WB 商品卡 subject 与本轮类目模板不一致，已拒绝自动接管', true);
  }
  if (submissionMode === 'COMPATIBLE_UPSERT') {
    const colorId = Number(runtime.colorCharacteristicId || 0);
    if (colorId > 0) {
      for (const card of found) {
        const variant = (product.variants || []).find((entry) => String(entry.vendorCode) === String(card.vendorCode));
        const desired = (variant?.characteristics || []).find((entry) => Number(entry.id) === colorId);
        const current = (card.characteristics || []).find((entry) => Number(entry.id || entry.charcID) === colorId);
        const desiredValues = (Array.isArray(desired?.value) ? desired.value : [desired?.value]).filter((value) => value != null).map(String);
        const currentValues = (Array.isArray(current?.value) ? current.value : [current?.value]).filter((value) => value != null).map(String);
        if (!desiredValues.length || (currentValues.length && !desiredValues.some((value) => currentValues.includes(value)))) {
          return businessFail('COMPATIBLE_COLOR_MISMATCH', '既有 WB 商品卡颜色身份与 product.json 无法安全匹配: ' + String(card.vendorCode), true);
        }
      }
    }
  }

  if (['MEDIA_RECONCILING','MEDIA_VERIFYING','MEDIA_SUBMITTING','MEDIA_TRIM_SUBMITTING','VIDEO_RECONCILING','VIDEO_VERIFYING','VIDEO_SUBMITTING','FINAL_VERIFYING'].includes(currentState)) {
    if (found.length !== expectedCount) return platformPending('CARD_TEMPORARILY_MISSING', '媒体或终验阶段未查询到全部卡片');
    const previousCards = Array.isArray(runtime.cards) ? runtime.cards : [];
    const previousIntentItems = mediaIntentItems();
    const beforePhotosByVendor = runtime.mediaIntent?.beforePhotosByVendor || Object.fromEntries(previousCards.map((card) => [String(card.vendorCode), Number(card.photosCount || 0)]));
    const beforeVideoByVendor = runtime.mediaIntent?.beforeVideoByVendor || Object.fromEntries(previousCards.map((card) => [String(card.vendorCode), Boolean(card.videoPresent)]));
    let cardsRuntime;
    try { cardsRuntime = cardRuntime(found); }
    catch (error) { return businessFail(String(error.code || 'SIZE_IDENTITY_AMBIGUOUS'), safe(error.message), true); }
    let reusedChrtIds = 0;
    cardsRuntime.forEach((card) => {
      const previous = previousCards.find((entry) => String(entry.vendorCode) === String(card.vendorCode));
      card.sizes.forEach((size) => {
        if (size.chrtID) return;
        const previousSize = (previous?.sizes || []).find((entry) => String(entry.barcode) === String(size.barcode));
        if (!previousSize?.chrtID) return;
        size.chrtID = String(previousSize.chrtID);
        if (!size.wbSize && previousSize.wbSize) size.wbSize = String(previousSize.wbSize);
        reusedChrtIds++;
      });
    });
    if (reusedChrtIds) runtime.audit.push({
      at: new Date().toISOString(), event: 'CHRTID_REUSED_DURING_MEDIA_VERIFY', executionId: String($execution.id), count: reusedChrtIds,
    });
    runtime.cards = cardsRuntime;
    runtime.existingCardsRaw = found;
    const pendingChrt = unresolvedChrtResult(cardsRuntime);
    if (pendingChrt) return pendingChrt;
    if (currentState === 'MEDIA_TRIM_SUBMITTING') {
      const trim = runtime.mediaTrimIntent || (runtime.mediaTrimQueue || [])[0];
      if (!trim) return persist('VIDEO_RECONCILING', 2);
      const card = cardsRuntime.find((entry) => String(entry.vendorCode) === String(trim.vendorCode)
        || String(entry.nmID) === String(trim.nmID));
      const desired = Number(trim.desired ?? (trim.photoUrls || []).length);
      const applied = Boolean(card) && Number(card.photosCount || 0) === desired
        && (!trim.removeVideo || !card.videoPresent);
      if (applied) {
        runtime.audit.push({
          at: new Date().toISOString(), event: 'MEDIA_TRIM_RECONCILED', executionId: String($execution.id),
          vendorCode: String(trim.vendorCode || ''), nmID: String(trim.nmID || ''), desired,
        });
        runtime.mediaTrimQueue = (runtime.mediaTrimQueue || []).filter((entry) => String(entry.vendorCode) !== String(trim.vendorCode));
        runtime.mediaTrimIntent = null;
        runtime.mediaTrimAmbiguityStartedAt = '';
        return runtime.mediaTrimQueue.length ? persist('MEDIA_TRIM_READY', 1) : persist('VIDEO_RECONCILING', 2);
      }
      runtime.mediaTrimAmbiguityStartedAt = runtime.mediaTrimAmbiguityStartedAt || new Date().toISOString();
      const readableMillis = Date.now() - Date.parse(runtime.mediaTrimAmbiguityStartedAt);
      runtime.audit.push({
        at: new Date().toISOString(), event: 'MEDIA_TRIM_READBACK_MISMATCH', executionId: String($execution.id),
        vendorCode: String(trim.vendorCode || ''), nmID: String(trim.nmID || ''), desired,
        actualPhotos: Number(card?.photosCount || 0), actualVideoPresent: Boolean(card?.videoPresent),
      });
      if (Number.isFinite(readableMillis) && readableMillis >= 24 * 60 * 60 * 1000) {
        return needsAttention('MEDIA_TRIM_RESULT_AMBIGUOUS', '平台已恢复可读，但媒体裁剪写入结果累计 24 小时仍无法确认；保留原任务供人工兜底');
      }
      // A successful platform read proved that the prior write did not reach the desired state.
      // Reissue the same intent; no new task, vendorCode, nmID, or media plan is created.
      return persist('MEDIA_TRIM_READY', 1, 'MEDIA_TRIM_NOT_APPLIED', '平台回读确认媒体裁剪尚未生效，继续原任务补做');
    }
    if (runtime.compatibleRecovery?.verifyMediaBeforeSkip === true) {
      const mediaDiffs = cardsRuntime.flatMap((card, variantIndex) => {
        const variant = product.variants[variantIndex] || {};
        const desiredPhotos = Number((variant.images || []).length);
        const desiredVideo = Boolean(variant.video);
        const diffs = [];
        if (Number(card.photosCount || 0) !== desiredPhotos) diffs.push({ vendorCode: card.vendorCode, kind: 'images', current: Number(card.photosCount || 0), desired: desiredPhotos });
        if (Boolean(card.videoPresent) !== desiredVideo) diffs.push({ vendorCode: card.vendorCode, kind: 'video', current: Boolean(card.videoPresent), desired: desiredVideo });
        return diffs;
      });
      runtime.compatibleRecovery.verifyMediaBeforeSkip = false;
      runtime.audit.push({
        at: new Date().toISOString(), event: mediaDiffs.length ? 'COMPATIBLE_RECOVERY_MEDIA_DIFF' : 'COMPATIBLE_RECOVERY_MEDIA_VERIFIED_SKIP',
        executionId: String($execution.id), differences: mediaDiffs,
      });
      if (!mediaDiffs.length) {
        runtime.mediaQueue = [];
        runtime.mediaQueueIndex = 0;
        runtime.mediaReplayFromByVendor = {};
        runtime.videoQueue = [];
        runtime.videoQueueIndex = 0;
        runtime.mediaIntent = null;
        runtime.mediaBatchHadTransient = false;
        return persist('PRICE_RECONCILING', 2);
      }
      runtime.compatibleRecoveryMediaMissingOnly = true;
      runtime.forceMediaReplace = false;
    }
    if (currentState === 'FINAL_VERIFYING') {
      const incomplete = cardsRuntime.find((card, variantIndex) => {
        const variant = product.variants[variantIndex];
        const desiredPhotos = Number((variant.images || []).length);
        const photosInvalid = runtime.compatibleRecoveryMediaMissingOnly === true
          ? Number(card.photosCount || 0) < desiredPhotos
          : Number(card.photosCount || 0) !== desiredPhotos;
        return photosInvalid || (variant.video && !card.videoPresent);
      });
      if (incomplete) return businessFail('FINAL_MEDIA_VERIFY_FAILED', '终验时图片数量或视频状态不符合预期: ' + incomplete.vendorCode, true);
      return persist('FINALIZING', 0);
    }
    const successfulKeys = new Set(Array.isArray(runtime.successfulMediaUploadKeys) ? runtime.successfulMediaUploadKeys : []);

    function advanceVideoFromCurrentCards({ trackVerificationProgress = false, reusedMediaSnapshot = false } = {}) {
      const videoQueue = [];
      let videoPropagationPending = false;
      cardsRuntime.forEach((card, variantIndex) => {
        const variant = product.variants[variantIndex];
        if (!variant.video) return;
        const key = String(card.vendorCode) + '|video|1';
        if (!replaceMediaFor(card.vendorCode) && !card.videoPresent && successfulKeys.has(key)) {
          const accepted = [...runtime.audit].reverse().find((entry) => entry.event === 'MEDIA_UPLOAD_RESPONSE'
            && entry.kind === 'video' && entry.ok && String(entry.vendorCode) === String(card.vendorCode));
          const acceptedAt = Date.parse(accepted?.at || 0);
          if (!Number.isFinite(acceptedAt) || Date.now() - acceptedAt < 15 * 60 * 1000) {
            videoPropagationPending = true;
            return;
          }
          successfulKeys.delete(key);
          runtime.successfulMediaUploadKeys = Array.from(successfulKeys);
          runtime.audit.push({
            at: new Date().toISOString(), event: 'VIDEO_PROPAGATION_TIMEOUT', executionId: String($execution.id),
            vendorCode: String(card.vendorCode), nmID: String(card.nmID), waitedSeconds: Math.round((Date.now() - acceptedAt) / 1000),
          });
        }
        const needsUpload = replaceMediaFor(card.vendorCode) ? !successfulKeys.has(key) : !card.videoPresent;
        if (!needsUpload) return;
        const info = (runtime.videoInfo || []).find((entry) => entry.variantIndex === variantIndex);
        videoQueue.push({
          kind: 'video', vendorCode: card.vendorCode, nmID: card.nmID, variantIndex, imageIndex: 0,
          photoNumber: 1, relativePath: variant.video, mimeType: info?.mimeType || 'application/octet-stream', sha256: info?.sha256 || '',
          videoUploadMode: String(product.videoUploadMode || 'ORIGINAL').toUpperCase(),
        });
      });
      if (trackVerificationProgress && previousIntentItems.length) {
        const progressed = (runtime.lastMediaBatchResults || []).some((entry) => entry.kind === 'video' && entry.ok)
          || cardsRuntime.some((card) => card.videoPresent && !beforeVideoByVendor[String(card.vendorCode)]);
        if (progressed || videoQueue.length === 0) runtime.videoNoProgressBatches = 0;
        else runtime.videoNoProgressBatches = Number(runtime.videoNoProgressBatches || 0) + 1;
        if (!progressed && videoQueue.length && Number(runtime.videoNoProgressBatches || 0) >= 3) {
          return businessFail('VIDEO_UPLOAD_NO_PROGRESS', '连续 3 个视频批次未取得进展', true);
        }
      }
      runtime.videoQueue = videoQueue;
      runtime.videoQueueIndex = 0;
      runtime.mediaIntent = null;
      runtime.mediaBatchHadTransient = false;
      if (reusedMediaSnapshot) runtime.audit.push({
        at: new Date().toISOString(), event: 'MEDIA_CARD_SNAPSHOT_REUSED_FOR_VIDEO_QUEUE', executionId: String($execution.id),
        cardCount: cardsRuntime.length, queuedVideos: videoQueue.length,
      });
      if (videoPropagationPending) return persist('VIDEO_VERIFYING', 30, 'VIDEO_PROPAGATING', 'WB 已接受视频，等待商品卡返回 video 字段');
      if (videoQueue.length) return persist('VIDEO_UPLOAD_READY', 1);
      return persist('PRICE_RECONCILING', 2);
    }
    if (['VIDEO_RECONCILING','VIDEO_VERIFYING','VIDEO_SUBMITTING'].includes(currentState)) {
      return advanceVideoFromCurrentCards({ trackVerificationProgress: ['VIDEO_VERIFYING','VIDEO_SUBMITTING'].includes(currentState) });
    }

    const queue = [];
    function mediaQueueEntry(card, variantIndex, imageIndex) {
      const info = (runtime.imageInfo || []).find((entry) => entry.variantIndex === variantIndex && entry.imageIndex === imageIndex);
      return {
        kind: 'image', vendorCode: card.vendorCode, nmID: card.nmID, variantIndex, imageIndex, photoNumber: imageIndex + 1,
        relativePath: product.variants[variantIndex].images[imageIndex], mimeType: info?.mimeType || 'application/octet-stream', sha256: info?.sha256 || '',
      };
    }
    cardsRuntime.forEach((card, variantIndex) => {
      const desired = (product.variants[variantIndex].images || []).length;
      const replaceTarget = replaceMediaFor(card.vendorCode);
      if (card.photosCount > desired && !replaceTarget) {
        if (runtime.compatibleRecoveryMediaMissingOnly === true) {
          runtime.audit.push({
            at: new Date().toISOString(), event: 'COMPATIBLE_RECOVERY_EXTRA_MEDIA_PRESERVED', executionId: String($execution.id),
            vendorCode: String(card.vendorCode), current: Number(card.photosCount || 0), desired,
          });
          return;
        }
        queue.push({ error: 'MEDIA_SHRINK_REQUIRES_REPLACE_POLICY', vendorCode: card.vendorCode, current: card.photosCount, desired });
        return;
      }
      const replayState = runtime.mediaReplayFromByVendor && typeof runtime.mediaReplayFromByVendor === 'object' ? runtime.mediaReplayFromByVendor : {};
      const replayFrom = Number(replayState[String(card.vendorCode)] || 0);
      const start = replaceTarget ? Math.max(0, replayFrom ? replayFrom - 1 : 0) : Number(card.photosCount || 0);
      for (let imageIndex = start; imageIndex < desired; imageIndex++) {
        const key = String(card.vendorCode) + '|image|' + String(imageIndex + 1);
        if (!replaceTarget || replayFrom > 0 || !successfulKeys.has(key)) queue.push(mediaQueueEntry(card, variantIndex, imageIndex));
      }
    });
    const shrink = queue.find((entry) => entry.error);
    if (shrink) return businessFail(shrink.error, 'WB 已有图片数多于新版本，但当前任务没有启用安全替换策略: ' + shrink.vendorCode, true);
    if (!runtime.forceMediaReplace && runtime.mediaBatchHadTransient && previousIntentItems.length && Array.isArray(runtime.lastMediaBatchResults)) {
      const transientResults = runtime.lastMediaBatchResults.filter((entry) => !entry.ok && (Number(entry.status || 0) === 0 || Number(entry.status) === 429 || Number(entry.status) >= 500));
      const replayFromByVendor = new Map();
      transientResults.forEach((entry) => {
        const card = cardsRuntime.find((candidate) => String(candidate.vendorCode) === String(entry.vendorCode));
        const variantIndex = cardsRuntime.indexOf(card);
        const desired = variantIndex >= 0 ? (product.variants[variantIndex].images || []).length : 0;
        if (!card || Number(card.photosCount || 0) >= desired) return;
        const photoNumber = Number(entry.photoNumber || 0);
        if (photoNumber > 0 && photoNumber <= Number(card.photosCount || 0)) {
          const current = replayFromByVendor.get(String(entry.vendorCode));
          replayFromByVendor.set(String(entry.vendorCode), current ? Math.min(current, photoNumber) : photoNumber);
        }
      });
      replayFromByVendor.forEach((photoNumber, vendorCode) => {
        const card = cardsRuntime.find((candidate) => String(candidate.vendorCode) === vendorCode);
        const variantIndex = cardsRuntime.indexOf(card);
        const desired = (product.variants[variantIndex].images || []).length;
        for (let imageIndex = photoNumber - 1; imageIndex < desired; imageIndex++) {
          const entry = mediaQueueEntry(card, variantIndex, imageIndex);
          const key = String(entry.vendorCode) + '|' + String(entry.photoNumber);
          if (!queue.some((candidate) => String(candidate.vendorCode) + '|' + String(candidate.photoNumber) === key)) queue.push(entry);
        }
        runtime.audit.push({
          at: new Date().toISOString(), event: 'MEDIA_REPLAY_SUFFIX', executionId: String($execution.id),
          vendorCode, fromPhotoNumber: photoNumber, reason: '临时错误发生后已有后续图片成功；重放尾段以恢复图片顺序',
        });
      });
      queue.sort((a, b) => Number(a.variantIndex || 0) - Number(b.variantIndex || 0) || Number(a.imageIndex || 0) - Number(b.imageIndex || 0) || Number(a.photoNumber || 0) - Number(b.photoNumber || 0));
    }
    if (['MEDIA_VERIFYING','MEDIA_SUBMITTING'].includes(currentState) && previousIntentItems.length) {
      const progressed = mediaPolicy === 'REPLACE_SELECTED' || runtime.forceMediaReplace
        ? (runtime.lastMediaBatchResults || []).some((entry) => entry.kind !== 'video' && entry.ok)
        : cardsRuntime.some((card) => Number(card.photosCount || 0) > Number(beforePhotosByVendor[String(card.vendorCode)] || 0));
      if (progressed || queue.length === 0) runtime.mediaNoProgressBatches = 0;
      else runtime.mediaNoProgressBatches = Number(runtime.mediaNoProgressBatches || 0) + 1;
      runtime.audit.push({
        at: new Date().toISOString(), event: 'MEDIA_VERIFY_PROGRESS', executionId: String($execution.id), progressed,
        noProgressBatches: Number(runtime.mediaNoProgressBatches || 0), remaining: queue.length,
      });
      if (!progressed && queue.length && Number(runtime.mediaNoProgressBatches || 0) >= 3) {
        const failedNumbers = previousIntentItems.map((entry) => Number(entry.photoNumber || 0)).filter(Boolean).join(',');
        return businessFail('MEDIA_UPLOAD_NO_PROGRESS', '连续 3 个媒体批次未增加图片数，最近批次图片编号: ' + failedNumbers, true);
      }
    }
    runtime.mediaQueue = queue;
    runtime.mediaQueueIndex = 0;
    runtime.mediaIntent = null;
    runtime.mediaBatchHadTransient = false;
    if (queue.length) return persist('MEDIA_UPLOAD_READY', 1);
    runtime.mediaReplayFromByVendor = {};
    const trimQueue = [];
    cardsRuntime.forEach((card, variantIndex) => {
      if (!replaceMediaFor(card.vendorCode)) return;
      const variant = product.variants[variantIndex];
      const desired = (variant.images || []).length;
      if (Number(card.photosCount || 0) <= desired && (variant.video || !card.videoPresent)) return;
      const photoUrls = (card.photos || []).slice(0, desired).map((photo) => String(photo.big || photo.c516x688 || photo.c246x328 || '')).filter(Boolean);
      if (photoUrls.length !== desired) return;
      trimQueue.push({ vendorCode: String(card.vendorCode), nmID: String(card.nmID), desired, photoUrls, removeVideo: !variant.video && card.videoPresent });
    });
    runtime.mediaTrimQueue = trimQueue;
    if (trimQueue.length) return persist('MEDIA_TRIM_READY', 1);
    if (currentState === 'MEDIA_SUBMITTING' || currentState === 'MEDIA_VERIFYING' || currentState === 'MEDIA_RECONCILING') {
      return advanceVideoFromCurrentCards({ reusedMediaSnapshot: true });
    }
  }

  if (found.length === expectedCount) {
    if (submissionMode === 'CREATE_ONLY' && !currentTaskOwnsCreateIntent) {
      runtime.existingCardMatches = found.map((card) => ({ scope: 'active', vendorCode: String(card.vendorCode || ''), nmID: String(card.nmID || ''), imtID: String(card.imtID || '') }));
      return persist('BLOCKED_EXISTING_CARD', 315360000, 'BLOCKED_EXISTING_CARD', 'CREATE_ONLY 检测到外部既有商品卡，禁止自动接管');
    }
    const imtIds = new Set(found.map((card) => String(card.imtID)));
    if (imtIds.size !== 1) return businessFail('IMT_GROUP_MISMATCH', '颜色变体未归入同一 imtID', true);
    if (found.some((card) => card.needKiz && !card.kizMarked)) return persist('BLOCKED_COMPLIANCE', 86400, 'KIZ_STATE_MISMATCH', 'WB 返回 needKiz=true 但 kizMarked=false');
    if (submissionMode === 'CREATE_ONLY' && currentTaskOwnsCreateIntent) {
      runtime.audit.push({
        at: new Date().toISOString(), event: 'CREATE_ONLY_SELF_OWNED_CARDS_ACCEPTED', executionId: String($execution.id),
        taskId: job.task_id, count: found.length,
        vendorCodes: found.map((card) => String(card.vendorCode || '')).filter(Boolean),
      });
    }
    try { runtime.cards = cardRuntime(found); }
    catch (error) { return businessFail(String(error.code || 'SIZE_IDENTITY_AMBIGUOUS'), safe(error.message), true); }
    runtime.existingCardsRaw = found;
    const pendingChrt = unresolvedChrtResult(runtime.cards);
    if (pendingChrt) return pendingChrt;
    if (currentState === 'CARD_RECONCILING') {
      if (runtime.isUpdate) return persist('CARD_UPDATE_READY', 1);
      if (!runtime.cardSubmittedAt) return businessFail('EXTERNAL_CARD_CONFLICT', 'vendorCode 已存在但不属于当前任务；禁止自动接管', true);
    }
    if (runtime.pendingUpdateAfterAdd) {
      runtime.pendingUpdateAfterAdd = false;
      return persist('CARD_UPDATE_READY', 1);
    }
    return persist('MEDIA_RECONCILING', 2);
  }

  if (found.length > 0) {
    if (submissionMode === 'CREATE_ONLY' && !currentTaskOwnsCreateIntent) {
      runtime.existingCardMatches = found.map((card) => ({ scope: 'active', vendorCode: String(card.vendorCode || ''), nmID: String(card.nmID || ''), imtID: String(card.imtID || '') }));
      return persist('BLOCKED_EXISTING_CARD', 315360000, 'BLOCKED_EXISTING_CARD', 'CREATE_ONLY 检测到部分外部既有商品卡，禁止新增颜色或更新');
    }
    runtime.existingCardsRaw = found;
    try { runtime.cards = cardRuntime(found); }
    catch (error) { return businessFail(String(error.code || 'SIZE_IDENTITY_AMBIGUOUS'), safe(error.message), true); }
    runtime.missingVendorCodes = (product.variants || []).map((variant) => String(variant.vendorCode)).filter((code) => !found.some((card) => String(card.vendorCode) === code));
    job.partial_effects = true;
    const pendingChrt = unresolvedChrtResult(runtime.cards);
    if (pendingChrt) return pendingChrt;
    if (currentState === 'CARD_RECONCILING' && runtime.isUpdate && !runtime.cardSubmittedAt) {
      if (submissionMode === 'COMPATIBLE_UPSERT') {
        const missingCodes = new Set(runtime.missingVendorCodes.map(String));
        const missingSlots = [];
        (product.variants || []).forEach((variant, variantIndex) => {
          if (!missingCodes.has(String(variant.vendorCode))) return;
          (variant.sizes || []).forEach((size, sizeIndex) => {
            if (!String(size.barcode || runtime.barcodes?.[variantIndex + ':' + sizeIndex] || '')) missingSlots.push({ variantIndex, sizeIndex });
          });
        });
        runtime.missingBarcodeSlots = missingSlots;
        if (missingSlots.length) {
          runtime.afterBarcodeState = 'CARD_ADD_READY';
          return persist('BARCODE_ALLOCATING', 0);
        }
      }
      return persist('CARD_ADD_READY', 1);
    }
    const cardWriteIssued = ['create','add','update'].includes(String(runtime.cardOperation || '')) && Boolean(runtime.cardSubmittedAt);
    const submittedAt = Date.parse(runtime.cardSubmittedAt || 0);
    const lastErrorCheckAt = Date.parse(runtime.lastCardErrorCheckAt || 0);
    const shouldCheckErrors = cardWriteIssued && Number.isFinite(submittedAt)
      && Date.now() - submittedAt >= 60 * 1000
      && (!Number.isFinite(lastErrorCheckAt) || Date.now() - lastErrorCheckAt >= 120 * 1000);
    if (shouldCheckErrors) return persist('CARD_ERROR_RECONCILING', 1, 'CARD_PARTIAL_RECONCILING', '部分颜色已创建，正在查询其余颜色的 WB 错误详情');
    if (Date.now() < Date.parse(job.stage_deadline_at || 0)) {
      job.poll_count = Number(job.poll_count || 0) + 1;
      return persist('CARD_WAITING', 30, 'CARD_PARTIAL_PROPAGATION', '部分颜色尚未同步');
    }
    return cardWriteIssued
      ? persist('CARD_ERROR_RECONCILING', 1)
      : businessFail('CARD_RECONCILE_TIMEOUT', '既有卡片对账未完成，且本任务没有卡片写入意图；不会查询创建错误列表', true);
  }

  const recoverablePreCreateWait = currentState === 'CARD_WAITING'
    && submissionMode === 'COMPATIBLE_UPSERT'
    && !runtime.isUpdate
    && !runtime.cardSubmittedAt
    && !runtime.cardOperation
    && !runtime.cardCreateIntent
    && (!Array.isArray(runtime.cards) || runtime.cards.length === 0);
  if ((currentState === 'CARD_RECONCILING' || recoverablePreCreateWait) && !runtime.isUpdate && !runtime.cardSubmittedAt) {
    if (recoverablePreCreateWait) runtime.audit.push({
      at: new Date().toISOString(), event: 'PRECREATE_CARD_WAIT_RECOVERED', executionId: String($execution.id),
      reason: '历史请求携带了错误的 VALIDATING resumeState；实时空卡查询后恢复建卡前状态',
    });
    if (submissionMode === 'CREATE_ONLY') return persist('CARD_CREATE_GUARD', 0);
    if (submissionMode === 'COMPATIBLE_UPSERT') {
      const missingSlots = [];
      (product.variants || []).forEach((variant, variantIndex) => (variant.sizes || []).forEach((size, sizeIndex) => {
        if (!String(size.barcode || runtime.barcodes?.[variantIndex + ':' + sizeIndex] || '')) missingSlots.push({ variantIndex, sizeIndex });
      }));
      runtime.missingBarcodeSlots = missingSlots;
      if (missingSlots.length) {
        runtime.afterBarcodeState = 'CARD_CREATE_READY';
        return persist('BARCODE_ALLOCATING', 0);
      }
    }
    return persist('CARD_CREATE_READY', 1);
  }
  if (['CARD_RECONCILING', 'CARD_WAITING'].includes(currentState) && runtime.isUpdate && !runtime.cardSubmittedAt) {
    if (anchorCards.length) {
      const subjectIds = new Set(anchorCards.map((card) => Number(card.subjectID || card.subjectId || 0)).filter(Boolean));
      if (subjectIds.size !== 1 || !subjectIds.has(Number(runtime.expectedSubjectId || 0))) {
        return businessFail('UPSERT_ANCHOR_SUBJECT_MISMATCH', '历史商品卡 subject 与本次类目模板不一致，已拒绝新增颜色');
      }
      const imtIds = new Set(anchorCards.map((card) => String(card.imtID || '')).filter(Boolean));
      if (imtIds.size !== 1 || !/^\d+$/.test([...imtIds][0] || '')) return businessFail('UPSERT_ANCHOR_GROUP_MISMATCH', '历史商品注册记录对应多个或无效商品组，无法安全新增颜色');
      runtime.existingCardsRaw = anchorCards;
      runtime.cards = [];
      runtime.missingVendorCodes = [...expectedVendorCodes];
      runtime.cardAddAnchor = {
        vendorCode: String(anchorCards[0].vendorCode || ''),
        nmID: String(anchorCards[0].nmID || ''),
        imtID: [...imtIds][0],
      };
      runtime.audit.push({
        at: new Date().toISOString(), event: 'UPSERT_ADD_ANCHOR_RESOLVED', executionId: String($execution.id),
        anchorVendorCode: runtime.cardAddAnchor.vendorCode, imtID: runtime.cardAddAnchor.imtID,
        missingVendorCodes: runtime.missingVendorCodes,
      });
      return persist('CARD_ADD_READY', 1);
    }
    runtime.registryReconcileStartedAt = runtime.registryReconcileStartedAt || new Date().toISOString();
